125	// ─── CRUD Mutations ───────────────────────────────────────────────────────────
126	
127	export function useCreatePipelineStage(teamId: string) {
128	  const queryClient = useQueryClient();
129	
130	  return useMutation({
131	    mutationFn: async (input: { name: string; color: string }) => {
132	      // Determine next sort_order
133	      const existing = queryClient.getQueryData<PipelineStage[]>(["pipeline-stages", teamId]) ?? [];
134	      const maxOrder = existing.reduce((m, s) => Math.max(m, s.sort_order), -1);
135	
136	      const { data, error } = await (supabase as any)
137	        .from("pipeline_stages")
138	        .insert({ team_id: teamId, name: input.name, color: input.color, sort_order: maxOrder + 1 })
139	        .select()
140	        .single();
141	
142	      if (error) throw error;
143	      return data as PipelineStage;
144	    },
145	    onSuccess: () => {
146	      queryClient.invalidateQueries({ queryKey: ["pipeline-stages", teamId] });
147	      toast.success("Stage created");
148	    },
149	    onError: (err: Error) => {
150	      toast.error(err.message ?? "Failed to create stage");
151	    },
152	  });
153	}
154	
155	export function useUpdatePipelineStage(teamId: string) {
156	  const queryClient = useQueryClient();
157	
158	  return useMutation({
159	    mutationFn: async (input: { id: string; name?: string; color?: string }) => {
160	      const { id, ...rest } = input;
161	      const { error } = await (supabase as any)
162	        .from("pipeline_stages")
163	        .update(rest)
164	        .eq("id", id);
165	      if (error) throw error;
166	    },
167	    onSuccess: () => {
168	      queryClient.invalidateQueries({ queryKey: ["pipeline-stages", teamId] });
169	      toast.success("Stage updated");
170	    },
171	    onError: (err: Error) => {
172	      toast.error(err.message ?? "Failed to update stage");
173	    },
174	  });
175	}
176	
177	export function useDeletePipelineStage(teamId: string) {
178	  const queryClient = useQueryClient();
179	
180	  return useMutation({
181	    mutationFn: async (id: string) => {
182	      const { error } = await (supabase as any)
183	        .from("pipeline_stages")
184	        .delete()
185	        .eq("id", id);
186	      if (error) throw error;
187	    },
188	    onSuccess: () => {
189	      queryClient.invalidateQueries({ queryKey: ["pipeline-stages", teamId] });
190	      toast.success("Stage deleted");
191	    },
192	    onError: (err: Error) => {
193	      toast.error(err.message ?? "Failed to delete stage");
194	    },
195	  });
196	}
197	
198	export function useReorderPipelineStages(teamId: string) {
199	  const queryClient = useQueryClient();
200	
201	  return useMutation({
202	    mutationFn: async (ordered: PipelineStage[]) => {
203	      // Batch update sort_order via individual upserts
204	      const updates = ordered.map((s, i) =>
205	        (supabase as any)
206	          .from("pipeline_stages")
207	          .update({ sort_order: i })
208	          .eq("id", s.id)
209	      );
210	      await Promise.all(updates);
211	    },
212	    onMutate: async (ordered) => {
213	      await queryClient.cancelQueries({ queryKey: ["pipeline-stages", teamId] });
214	      const previous = queryClient.getQueryData<PipelineStage[]>(["pipeline-stages", teamId]);
215	      queryClient.setQueryData<PipelineStage[]>(
216	        ["pipeline-stages", teamId],
217	        ordered.map((s, i) => ({ ...s, sort_order: i }))
218	      );
219	      return { previous };
220	    },
221	    onError: (_err, _vars, context) => {
222	      if (context?.previous) {
223	        queryClient.setQueryData(["pipeline-stages", teamId], context.previous);
224	      }
225	      toast.error("Failed to reorder stages");
226	    },
227	    onSettled: () => {
228	      queryClient.invalidateQueries({ queryKey: ["pipeline-stages", teamId] });
229	    },
230	  });
231	}
