3	import { useQuery } from "@tanstack/react-query";
4	import { supabase } from "@/integrations/supabase/client";
5	import { useAuth } from "@/hooks/useAuth";
6	
7	type TeamRole = "owner" | "admin" | "member";
8	
9	export interface TeamMember {
10	  id: string;
11	  user_id: string;
12	  role: TeamRole;
13	  created_at: string;
14	  email?: string;
15	}
16	
17	export interface TeamInvitation {
18	  id: string;
19	  email: string;
20	  role: TeamRole;
21	  created_at: string;
22	  expires_at: string | null;
23	  accepted_at: string | null;
24	}
25	
26	export interface Team {
27	  id: string;
28	  name: string;
29	  owner_user_id: string;
30	}
31	
32	export function useTeam() {
33	  const { user } = useAuth();
34	  const userId = user?.id;
35	
36	  const { data, isLoading, error, refetch } = useQuery({
37	    queryKey: ["team", userId],
38	    queryFn: async () => {
39	      if (!userId) return { team: null, members: [], invitations: [], myRole: null };
40	
41	      // Get user's team membership (prefer owned team, fallback to any team)
42	      const { data: allMemberships } = await (supabase as any)
43	        .from("team_members")
44	        .select("team_id, role")
45	        .eq("user_id", userId)
46	        .order("role");
47	
48	      // Pick the team where user is owner first, otherwise first membership
49	      const memberships = (allMemberships ?? []) as { team_id: string; role: string }[];
50	      const tmData = memberships.find((m) => m.role === "owner") ?? memberships[0] ?? null;
51	
52	      if (!tmData?.team_id) return { team: null, members: [], invitations: [], myRole: null };
53	
54	      const teamId = tmData.team_id;
55	
56	      // Fetch team, members, invitations in parallel
57	      const [teamRes, membersRes, invitationsRes] = await Promise.all([
58	        (supabase as any).from("teams").select("id, name, owner_user_id").eq("id", teamId).single(),
59	        (supabase as any).from("team_members").select("id, user_id, role, created_at").eq("team_id", teamId).order("created_at"),
60	        (supabase as any).from("team_invitations").select("id, email, role, created_at, expires_at, accepted_at").eq("team_id", teamId).is("accepted_at", null).order("created_at", { ascending: false }),
61	      ]);
62	
63	      const team: Team | null = teamRes.data ?? null;
64	      const rawMembers = (membersRes.data ?? []) as TeamMember[];
65	      const invitations = (invitationsRes.data ?? []) as TeamInvitation[];
66	
67	      // Augment current user's own record with their email; others show user_id until
68	      // a profiles.email column is available.
69	      const members = rawMembers.map((m) => ({
70	        ...m,
71	        email: m.user_id === userId ? user?.email ?? undefined : undefined,
72	      }));
73	
74	      return { team, members, invitations, myRole: tmData.role as TeamRole };
75	    },
76	    enabled: !!userId,
77	    staleTime: 60_000,
78	  });
79	
80	  return {
81	    team: data?.team ?? null,
82	    members: data?.members ?? [],
83	    invitations: data?.invitations ?? [],
84	    myRole: data?.myRole ?? null,
85	    isLoading,
86	    error,
87	    refetch,
88	  };
89	}
